#include <QApplication>
#include <QMainWindow>
#include <QPushButton>
#include <QVBoxLayout>
#include <QFileDialog>
#include <QDir>
#include <QFileInfo>
#include <QMessageBox>
#include <QProgressDialog>
#include <QDateTime>
#include <QFile>
#include <QTextStream>
#include <QDebug>

// QtXlsx headers
#include "xlsxdocument.h"
#include "xlsxworksheet.h"
#include "xlsxcellrange.h"

class ConverterWindow : public QMainWindow {
    Q_OBJECT

public:
    ConverterWindow(QWidget *parent = nullptr) : QMainWindow(parent) {
        setWindowTitle("Excel to CSV Converter");
        resize(400, 150);

        QWidget *centralWidget = new QWidget(this);
        QVBoxLayout *layout = new QVBoxLayout(centralWidget);

        QLabel *infoLabel = new QLabel(
            "Select a directory containing Excel files.\n"
            "All .xls/.xlsx files will be converted to CSVs\n"
            "in a new folder within the selected directory.",
            this
        );
        infoLabel->setAlignment(Qt::AlignCenter);
        infoLabel->setWordWrap(true);

        QPushButton *selectBtn = new QPushButton("Select Directory", this);
        connect(selectBtn, &QPushButton::clicked, this, &ConverterWindow::selectDirectory);

        layout->addStretch();
        layout->addWidget(infoLabel);
        layout->addWidget(selectBtn);
        layout->addStretch();

        centralWidget->setLayout(layout);
        setCentralWidget(centralWidget);
    }

private slots:
    void selectDirectory() {
        QString dirPath = QFileDialog::getExistingDirectory(
            this,
            "Select Directory with Excel Files",
            QDir::homePath()
        );

        if (dirPath.isEmpty()) return;

        QDir inputDir(dirPath);
        if (!inputDir.exists()) {
            QMessageBox::critical(this, "Error", "Directory does not exist!");
            return;
        }

        // Find Excel files
        QStringList nameFilters = {"*.xls", "*.xlsx"};
        inputDir.setNameFilters(nameFilters);
        inputDir.setFilter(QDir::Files | QDir::NoDotAndDotDot);
        QStringList excelFiles = inputDir.entryList();

        if (excelFiles.isEmpty()) {
            QMessageBox::information(this, "No Files Found", 
                "No Excel files (.xls or .xlsx) found in the selected directory.");
            return;
        }

        // Create timestamped output directory
        QString timestamp = QDateTime::currentDateTime().toString("yyyyMMdd_hhmmss");
        QString outputDirName = QString("converted_csv_%1").arg(timestamp);
        QString outputDirPath = dirPath + QDir::separator() + outputDirName;

        QDir outputDir(outputDirPath);
        if (!outputDir.exists() && !outputDir.mkpath(".")) {
            QMessageBox::critical(this, "Error", 
                QString("Cannot create output directory:\n%1").arg(outputDirPath));
            return;
        }

        // Conversion progress dialog
        QProgressDialog progress("Converting Excel files...", "Cancel", 0, excelFiles.size(), this);
        progress.setWindowModality(Qt::WindowModal);
        progress.setWindowTitle("Conversion Progress");
        progress.setValue(0);
        progress.show();

        int successCount = 0;
        QStringList errors;

        for (int i = 0; i < excelFiles.size(); ++i) {
            if (progress.wasCanceled()) break;

            QString filePath = dirPath + QDir::separator() + excelFiles[i];
            QString baseName = QFileInfo(excelFiles[i]).baseName();

            try {
                QXlsx::Document xlsx(filePath);
                if (!xlsx.load()) {
                    throw std::runtime_error(QString("Failed to load: %1").arg(excelFiles[i]).toStdString());
                }

                // Process each worksheet
                for (const QString &sheetName : xlsx.sheetNames()) {
                    xlsx.selectSheet(sheetName);
                    QString safeSheetName = sheetName;
                    safeSheetName.replace(QRegExp("[^a-zA-Z0-9_]"), "_"); // Sanitize filename

                    QString csvPath = QString("%1/%2_%3.csv")
                        .arg(outputDirPath, baseName, safeSheetName);

                    if (!saveSheetToCsv(xlsx, sheetName, csvPath)) {
                        throw std::runtime_error(QString("Failed to save sheet: %1").arg(sheetName).toStdString());
                    }
                }
                successCount++;
            } catch (const std::exception &e) {
                errors.append(QString("%1: %2").arg(excelFiles[i], QString::fromStdString(e.what())));
                qDebug() << "Conversion error:" << e.what();
            }

            progress.setValue(i + 1);
            qApp->processEvents();
        }

        progress.close();

        // Show results
        QString summary = QString("Converted %1 of %2 files successfully.\nOutput folder:\n%3")
            .arg(successCount)
            .arg(excelFiles.size())
            .arg(outputDirPath);

        if (!errors.isEmpty()) {
            summary += "\n\nErrors occurred with:\n" + errors.join("\n");
            QMessageBox::warning(this, "Conversion Complete", summary);
        } else {
            QMessageBox::information(this, "Success", summary);
            // Open output folder (cross-platform)
            QDesktopServices::openUrl(QUrl::fromLocalFile(outputDirPath));
        }
    }

private:
    bool saveSheetToCsv(const QXlsx::Document &xlsx, const QString &sheetName, const QString &csvPath) {
        QFile csvFile(csvPath);
        if (!csvFile.open(QIODevice::WriteOnly | QIODevice::Text)) {
            return false;
        }

        QTextStream out(&csvFile);
        out.setCodec("UTF-8");

        // Get sheet dimensions
        QXlsx::Worksheet *sheet = xlsx.worksheet(sheetName);
        if (!sheet) return false;

        QXlsx::CellRange range = sheet->dimension();
        if (range.rowCount() <= 0 || range.columnCount() <= 0) {
            csvFile.close();
            return true; // Empty sheet - create empty file
        }

        // Write CSV content
        for (int row = range.firstRow(); row <= range.lastRow(); ++row) {
            QStringList line;
            for (int col = range.firstColumn(); col <= range.lastColumn(); ++col) {
                QString cellValue = sheet->read(row, col).toString();
                // Escape quotes and handle commas
                if (cellValue.contains(',') || cellValue.contains('"') || cellValue.contains('\n')) {
                    cellValue.replace('"', "\"\"");
                    cellValue = QString("\"%1\"").arg(cellValue);
                }
                line << cellValue;
            }
            out << line.join(",") << "\n";
        }

        csvFile.close();
        return true;
    }
};

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);
    ConverterWindow window;
    window.show();
    return app.exec();
}

